def _cytoscape_bundle_scripts() -> str:
    """The cytoscape core + layout-extension bundle as inline ``<script>``
    blocks (plan-offline-html-exports Phase A), read from the vendored
    ``src/assets/cytoscape/`` bundle of the surrounding repository. Falls
    back to the historical CDN tags when the bundle is not found (vispath
    is usable standalone outside the DROCAT checkout). HTML inlining
    neutralizes ONLY ``</script`` — a blanket ``</`` escape would corrupt
    JS regex literals."""
    bundle_dir = (Path(__file__).resolve().parents[3] / 'src' / 'assets'
                  / 'cytoscape')
    scripts = (
        'cytoscape.min.js',
        'dagre.min.js',
        'cytoscape-dagre.js',
        'layout-base.js',
        'cose-base.js',
        'cytoscape-cose-bilkent.js',
        'cytoscape-fcose.js',
        'klay.js',
        'cytoscape-klay.js',
        'cytoscape-svg.js',
    )
    cdn = (
        '<script src="https://cdnjs.cloudflare.com/ajax/libs/cytoscape/'
        '3.28.1/cytoscape.min.js"></script>\n'
        '<script src="https://unpkg.com/dagre@0.8.5/dist/dagre.min.js">'
        '</script>\n'
        '<script src="https://unpkg.com/cytoscape-dagre@2.5.0/'
        'cytoscape-dagre.js"></script>\n'
        '<script src="https://unpkg.com/layout-base@1.0.2/layout-base.js">'
        '</script>\n'
        '<script src="https://unpkg.com/cose-base@1.0.3/cose-base.js">'
        '</script>\n'
        '<script src="https://unpkg.com/cytoscape-cose-bilkent@4.1.0/'
        'cytoscape-cose-bilkent.js"></script>\n'
        '<script src="https://unpkg.com/cytoscape-fcose@2.2.0/'
        'cytoscape-fcose.js"></script>\n'
        '<script src="https://unpkg.com/klayjs@0.4.1/klay.js"></script>\n'
        '<script src="https://unpkg.com/cytoscape-klay@3.1.4/'
        'cytoscape-klay.js"></script>\n'
        '<script src="https://unpkg.com/cytoscape-svg@0.4.0/'
        'cytoscape-svg.js"></script>'
    )
    try:
        parts = []
        for name in scripts:
            lib = (bundle_dir / name).read_text(encoding='utf-8')
            parts.append('<script>' + re.sub(
                r'</(script)', r'<\\/\1', lib,
                flags=re.IGNORECASE) + '</script>')
        return '\n'.join(parts)
    except OSError:
        return cdn


def _json_default(o):
    """JSON encoder fallback for numpy scalars in embedded visualization data."""
    if isinstance(o, (np.integer, np.floating)):
        return float(o)
    if isinstance(o, np.bool_):
        return bool(o)
    return str(o)


def parse_color_to_hex_opacity(color_str):
    """
    Parse a color string (hex, rgb, rgba, named) into hex color and opacity.
    
    Parameters
    ----------
    color_str : str
        Color in any CSS format: '#3498db', 'rgb(52, 152, 219)', 
        'rgba(52, 152, 219, 0.5)', 'blue', etc.
    
    Returns
    -------
    tuple
        (hex_color: str, opacity: float) e.g., ('#3498db', 1.0)
    
    Examples
    --------
    >>> parse_color_to_hex_opacity('rgba(44, 160, 44, 0.2)')
    ('#2ca02c', 0.2)
    >>> parse_color_to_hex_opacity('#1f77b4')
    ('#1f77b4', 1.0)
    """
    if not color_str:
        return ('#000000', 1.0)
    
    color_str = color_str.strip()
    
    # Parse rgba(r, g, b, a) or rgb(r, g, b)
    rgba_match = re.match(r'rgba?\s*\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)\s*(?:,\s*([\d.]+))?\s*\)', color_str)
    if rgba_match:
        r = int(rgba_match.group(1))
        g = int(rgba_match.group(2))
        b = int(rgba_match.group(3))
        a = float(rgba_match.group(4)) if rgba_match.group(4) else 1.0
        hex_color = '#{:02x}{:02x}{:02x}'.format(r, g, b)
        return (hex_color, a)
    
    # Parse hex color #RRGGBB or #RGB
    if color_str.startswith('#'):
        hex_color = color_str
        # Expand #RGB to #RRGGBB
        if len(hex_color) == 4:
            hex_color = '#' + ''.join([c*2 for c in hex_color[1:]])
        return (hex_color, 1.0)
    
    # Named colors (basic support)
    named_colors = {
        'red': '#ff0000', 'green': '#00ff00', 'blue': '#0000ff',
        'white': '#ffffff', 'black': '#000000', 'gray': '#808080', 'grey': '#808080',
        'yellow': '#ffff00', 'cyan': '#00ffff', 'magenta': '#ff00ff',
        'orange': '#ffa500', 'purple': '#800080', 'pink': '#ffc0cb',
        'brown': '#a52a2a', 'navy': '#000080', 'teal': '#008080'
    }
    if color_str.lower() in named_colors:
        return (named_colors[color_str.lower()], 1.0)
    
    # Default fallback
    return (color_str, 1.0)


def blend_with_gray(hex_color, factor=0.4):
    """
    Desaturate a hex color by blending with mid-gray.
    factor=0 returns original color, factor=1 returns gray.
    """
    if not hex_color:
        return '#808080'
    hex_color = hex_color.strip()
    if not hex_color.startswith('#'):
        hex_color, _ = parse_color_to_hex_opacity(hex_color)
    if len(hex_color) == 4:
        hex_color = '#' + ''.join([c * 2 for c in hex_color[1:]])
    try:
        r = int(hex_color[1:3], 16)
        g = int(hex_color[3:5], 16)
        b = int(hex_color[5:7], 16)
    except Exception:
        return '#808080'
    gray = 128
    r = int(r * (1 - factor) + gray * factor)
    g = int(g * (1 - factor) + gray * factor)
    b = int(b * (1 - factor) + gray * factor)
    return f'#{r:02x}{g:02x}{b:02x}'


